const DAY=86400000;const now=Date.now();
const srcFor=(u)=>{u=(u||'').toLowerCase();if(u.includes('openai.com'))return 'OpenAI';if(u.includes('deepmind.google'))return 'Google DeepMind';if(u.includes('googleblog.com')||u.includes('research.google'))return 'Google Research';if(u.includes('huggingface.co'))return 'Hugging Face';if(u.includes('nvidia.com'))return 'NVIDIA';if(u.includes('microsoft.com'))return 'Microsoft AI';return 'Unknown';};
const seen=new Set();const stories=[];
for(const it of $input.all()){const j=it.json;const url=(j.link||j.url||j.guid||'').trim();const title=(j.title||'').trim();const pub=j.isoDate||j.pubDate||j.published||null;const ts=pub?Date.parse(pub):NaN;if(!title||!url)continue;if(!Number.isNaN(ts)&&(now-ts)>DAY)continue;const key=url.split('?')[0];if(seen.has(key))continue;seen.add(key);const snip=(j.contentSnippet||j.summary||j.content||'').replace(/\s+/g,' ').trim().slice(0,600);stories.push({source:srcFor(url),title,url,publishedAt:pub,snippet:snip});}
const SYSTEM=["You are the editor of an AI-news brand. You receive a JSON array of candidate stories collected today from official AI-lab sources.","","Your job:","1. DEDUPE stories covering the same announcement into one.","2. RANK; keep only genuinely significant items (model/product launches, major research, safety/policy, notable tooling). Drop minor or promotional posts.","3. SELECT the top 5 (fewer if the day is quiet; never pad).","4. For each, WRITE: summary (2-3 factual sentences, no hype or emojis), score (1-100), and platforms.","","Per-platform: x <=280 chars with the link and 1-2 hashtags; linkedin 3-5 professional sentences with the link at the end; instagram 2-3 caption lines with up to 5 hashtags and no link in the body; youtube a 30-45 second spoken Shorts/Reels script for the virtual ASI character (plain narration, no stage directions).","","Hard rules: use ONLY facts in each candidate title and snippet; never invent details, numbers, or quotes; keep every claim attributable to the official source; return ONLY the JSON object from the schema."].join('\n');
const SCHEMA={type:'object',properties:{stories:{type:'array',items:{type:'object',properties:{source:{type:'string'},title:{type:'string'},url:{type:'string'},summary:{type:'string'},score:{type:'integer'},platforms:{type:'object',properties:{x:{type:'string'},linkedin:{type:'string'},instagram:{type:'string'},youtube:{type:'string'}},required:['x','linkedin','instagram','youtube'],additionalProperties:false}},required:['source','title','url','summary','score','platforms'],additionalProperties:false}}},required:['stories'],additionalProperties:false};
const body={model:'claude-sonnet-4-6',max_tokens:8000,system:SYSTEM,messages:[{role:'user',content:"Today's candidate stories (JSON):\n\n"+JSON.stringify(stories)+"\n\nReturn the selected stories."}],output_config:{format:{type:'json_schema',schema:SCHEMA}}};
return [{json:{count:stories.length,stories,body}}];

const out=[];
for(const it of $input.all()){const content=(it.json.content)||[];const tb=content.find(b=>b.type==='text');if(!tb)continue;let parsed;try{parsed=JSON.parse(tb.text);}catch(e){continue;}for(const s of (parsed.stories||[])){out.push({json:s});}}
return out;
